import {loadScript,assetURL,pdfDocument,pdfPagesText,readText,imagesToPdf,blobDataURL,zipOutputs,convertFile} from './engine.mjs';
import {base,ext} from './core.mjs';
import {parsePageRange,parseSplitGroups,diffLines,overlayPlacement} from './pdf-catalog.mjs';
export async function pdfLib(){await loadScript('pdf-lib.js');return window.PDFLib;}
export async function openEditable(file){const {PDFDocument}=await pdfLib();const doc=await PDFDocument.load(await file.arrayBuffer());if(doc.isEncrypted)throw new Error('请先使用「解锁 PDF」移除加密后再编辑');if(doc.getPageCount()>100)throw new Error('一次最多处理 100 页，请先拆分文件');return doc;}
const result=(bytes,name,note='')=>({blob:bytes instanceof Blob?bytes:new Blob([bytes],{type:'application/pdf'}),name,note});
export async function savePDF(pdf,name,note=''){return result(await pdf.save({useObjectStreams:true}),name,note);}
export async function extractDocument(source,pages,name){const {PDFDocument}=await pdfLib();const out=await PDFDocument.create();for(const page of await out.copyPages(source,pages))out.addPage(page);return savePDF(out,name);}
export async function qpdfFile(file,args,signal){
 const data=await file.arrayBuffer();signal?.throwIfAborted();return new Promise((resolve,reject)=>{const worker=new Worker(new URL('./qpdf-worker.mjs',import.meta.url),{type:'module'});const finish=()=>{clearTimeout(timer);worker.terminate();signal?.removeEventListener('abort',abort);};const abort=()=>{finish();reject(new Error('任务已取消'));};const timer=setTimeout(()=>{finish();reject(new Error('QPDF 处理超时，请减小文件后重试'));},90000);signal?.addEventListener('abort',abort,{once:true});worker.onerror=()=>{finish();reject(new Error('QPDF 引擎加载失败，请刷新后重试'));};worker.onmessage=({data})=>{finish();data.error?reject(new Error(data.error)):resolve(new Uint8Array(data.output));};worker.postMessage({id:1,input:data,args},[data]);});
}
export async function renderPageCanvas(doc,pageNumber=1,scale=1.35){const page=await doc.getPage(pageNumber);let viewport=page.getViewport({scale});if(viewport.width*viewport.height>16e6){scale*=Math.sqrt(16e6/(viewport.width*viewport.height));viewport=page.getViewport({scale});}const canvas=document.createElement('canvas');canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);await page.render({canvasContext:canvas.getContext('2d'),viewport,background:'#ffffff'}).promise;return{canvas,page,viewport};}
export async function textPNG(text,{size=30,color='#273c2c',width=1100,align='left'}={}){
 await document.fonts.ready;const canvas=document.createElement('canvas');const ctx=canvas.getContext('2d');canvas.width=width;ctx.font=`${size}px "Noto Sans SC","Microsoft YaHei",sans-serif`;const lines=[];for(const para of String(text).split('\n')){let line='';for(const ch of para){if(ctx.measureText(line+ch).width>width-24){lines.push(line);line=ch;}else line+=ch;}lines.push(line);}canvas.height=Math.max(size*1.55*lines.length+12,size*1.6);ctx.font=`${size}px "Noto Sans SC","Microsoft YaHei",sans-serif`;ctx.fillStyle=color;ctx.textBaseline='top';ctx.textAlign=align;lines.forEach((line,i)=>ctx.fillText(line,align==='center'?width/2:8,6+i*size*1.55));return canvas.toDataURL('image/png');
}
export async function rasterPDF(file,options={},progress=()=>{}){
 const {PDFDocument}=await pdfLib(),out=await PDFDocument.create(),doc=await pdfDocument(file);try{for(let i=1;i<=doc.numPages;i++){options.signal?.throwIfAborted();const {canvas,page}=await renderPageCanvas(doc,i,options.scale||1.2);if(options.redactions){const ctx=canvas.getContext('2d');ctx.fillStyle='#000';for(const box of options.redactions.filter(b=>b.page===i)){ctx.fillRect(Math.floor(box.x*canvas.width)-2,Math.floor(box.y*canvas.height)-2,Math.ceil(box.w*canvas.width)+4,Math.ceil(box.h*canvas.height)+4);}}
 const image=await out.embedJpg(canvas.toDataURL('image/jpeg',options.quality||.8));const vp=page.getViewport({scale:1});const target=out.addPage([vp.width,vp.height]);target.drawImage(image,{x:0,y:0,width:vp.width,height:vp.height});canvas.width=0;canvas.height=0;page.cleanup();progress(i/doc.numPages,`正在重建第 ${i} / ${doc.numPages} 页`);}return savePDF(out,base(file.name)+(options.redactions?'_已永久遮盖':'_压缩')+'.pdf',options.redactions?'已重新渲染全部页面，所选区域原始文字、图层、表单与元数据不写入输出文件。':'图像型 PDF：不保留可选文字、表单、链接或数字签名。');}finally{await doc.loadingTask.destroy();}}
export async function getFormFields(file){const pdf=await openEditable(file);return pdf.getForm().getFields().map(field=>({name:field.getName(),type:field.constructor.name,value:field.getText?.()??field.getSelected?.()?.[0]??field.isChecked?.()??'',options:field.getOptions?.()||[]}));}
function fieldPage(pdf,widget){const ref=widget.P?.();return pdf.getPages().find(p=>p.ref===ref||p.ref.toString()===ref?.toString()||p.node.Annots()?.asArray().some(r=>pdf.context.lookup(r)===widget.dict))||pdf.getPages()[0];}
async function fillForms(pdf,options){const {rgb}=await pdfLib(),form=pdf.getForm();if(options.formMode==='create'){
 const page=pdf.getPages()[Math.max(0,(options.page||1)-1)],{width,height}=page.getSize();const definitions=(options.fieldsText||'姓名|name\n电子邮箱|email').split('\n').map(x=>x.trim()).filter(Boolean).slice(0,8);
 for(let i=0;i<definitions.length;i++){const[label,key]=definitions[i].split('|');const name=(key||'field_'+(i+1)).trim();if(form.getFields().some(f=>f.getName()===name))throw new Error(`字段名称重复：${name}`);const y=height*(1-(Number(options.y)||20)/100)-i*52;const labelImage=await pdf.embedPng(await textPNG(label,{size:24,width:380}));page.drawImage(labelImage,{x:width*.1,y:y+20,width:100,height:22});const field=form.createTextField(name);field.addToPage(page,{x:width*.3,y,width:width*.57,height:30,borderWidth:1,borderColor:rgb(.7,.75,.68)});}return;
 }
 const fields=form.getFields();if(!fields.length)throw new Error('文件中没有可填写表单，请切换为「创建文本表单」');
 for(const field of fields){const value=options.formValues?.[field.getName()]??field.getText?.()??field.getSelected?.()?.[0]??field.isChecked?.()??'';if(options.formEditable){if(typeof value==='string'&&/[^\x00-\x7f]/.test(value))throw new Error('保留可编辑表单时仅支持英数字；中文请选择扁平化填写');if(field.setText)field.setText(String(value));else if(field.check)value?field.check():field.uncheck();else if(field.select&&value)field.select(String(value));continue;}
 for(const widget of field.acroField.getWidgets()){const page=fieldPage(pdf,widget),rect=widget.getRectangle();page.drawRectangle({...rect,color:rgb(1,1,1),borderColor:rgb(.7,.75,.68),borderWidth:.7});if(typeof value==='boolean'){if(value){page.drawLine({start:{x:rect.x+4,y:rect.y+4},end:{x:rect.x+rect.width-4,y:rect.y+rect.height-4},color:rgb(.15,.3,.2),thickness:1.5});page.drawLine({start:{x:rect.x+4,y:rect.y+rect.height-4},end:{x:rect.x+rect.width-4,y:rect.y+4},color:rgb(.15,.3,.2),thickness:1.5});}}else if(value){const img=await pdf.embedPng(await textPNG(String(value),{size:24,width:Math.max(300,rect.width*3)}));page.drawImage(img,{x:rect.x+3,y:rect.y+3,width:rect.width-6,height:Math.min(rect.height-6,(rect.width-6)*img.height/img.width)});}}
 form.removeField(field);
 }
}
async function ocr(file,options,progress){await loadScript('tesseract/tesseract.min.js');const languages=options.language||'chi_sim+eng';const worker=await window.Tesseract.createWorker(languages,1,{workerPath:assetURL('tesseract/worker.min.js'),corePath:assetURL('tesseract/core/'),langPath:assetURL('tesseract/lang').replace(/\/$/,''),cacheMethod:'none',logger:m=>{if(m.status==='recognizing text')progress(m.progress*.9,`正在识别文字 ${Math.round(m.progress*100)}%`);}});let doc;const pages=[];try{doc=await pdfDocument(file);const selected=parsePageRange(options.range||'all',doc.numPages);if(selected.length>20)throw new Error('OCR 每次最多识别 20 页，请缩小页码范围');for(let j=0;j<selected.length;j++){options.signal?.throwIfAborted();const {canvas}=await renderPageCanvas(doc,selected[j]+1,1.8);const r=await worker.recognize(canvas);pages.push(r.data.text.trim());canvas.width=0;progress((j+1)/selected.length,`已识别 ${j+1} / ${selected.length} 页`);}const content=pages.join('\n\n---\n\n');if(!content.trim())throw new Error('未识别出文字，请检查页面清晰度和识别语言');if(options.output==='txt')return result(new Blob(['\ufeff'+content],{type:'text/plain;charset=utf-8'}),base(file.name)+'_OCR.txt','OCR 结果可能有误，请校对。');await loadScript('docx.js');const {Document,Packer,Paragraph,TextRun}=window.docx;const children=[];pages.forEach((p,i)=>p.split('\n').forEach((line,j)=>children.push(new Paragraph({pageBreakBefore:i>0&&j===0,children:[new TextRun({text:line,font:'Microsoft YaHei',size:22})]}))));return result(await Packer.toBlob(new Document({sections:[{children}]})),base(file.name)+'_OCR.docx','OCR 结果可能有误，请校对。');}finally{await worker.terminate();await doc?.loadingTask.destroy();}}
async function pdfToPpt(file,progress){await loadScript('pptxgen.js');const doc=await pdfDocument(file),ppt=new window.PptxGenJS();ppt.author='Forma';ppt.title=base(file.name);const first=await doc.getPage(1),v=first.getViewport({scale:1});ppt.defineLayout({name:'SOURCE',width:v.width/72,height:v.height/72});ppt.layout='SOURCE';try{for(let i=1;i<=doc.numPages;i++){const {canvas}=await renderPageCanvas(doc,i,1.45),slide=ppt.addSlide();const w=v.width/72,h=v.height/72,scale=Math.min(w/canvas.width,h/canvas.height);slide.addImage({data:canvas.toDataURL('image/jpeg',.92),x:(w-canvas.width*scale)/2,y:(h-canvas.height*scale)/2,w:canvas.width*scale,h:canvas.height*scale});canvas.width=0;progress(i/doc.numPages,`正在生成第 ${i} 张幻灯片`);}return result(await ppt.write({outputType:'blob'}),base(file.name)+'.pptx','每页作为整张图片保留视觉效果；页内文字不可单独编辑。');}finally{await doc.loadingTask.destroy();}}
async function pdfToExcel(file,progress){await loadScript('exceljs.js');const book=new window.ExcelJS.Workbook(),doc=await pdfDocument(file);try{for(let i=1;i<=doc.numPages;i++){const page=await doc.getPage(i),content=await page.getTextContent(),lines=[];for(const item of content.items){if(!item.str?.trim())continue;const y=item.transform[5],x=item.transform[4];let row=lines.find(r=>Math.abs(r.y-y)<3);if(!row){row={y,items:[]};lines.push(row);}row.items.push({x,text:item.str,width:item.width});}lines.sort((a,b)=>b.y-a.y);const sheet=book.addWorksheet('第'+i+'页');for(const row of lines){row.items.sort((a,b)=>a.x-b.x);const cells=[];let last=null;for(const item of row.items){if(last&&item.x-last.x-last.width<12)cells[cells.length-1]+=' '+item.text;else cells.push(item.text);last=item;}sheet.addRow(cells);}sheet.columns.forEach(c=>{c.width=Math.min(50,Math.max(16,...(c.values||[]).filter(Boolean).map(v=>String(v).length+2)));});progress(i/doc.numPages,'正在提取文字行列…');}return result(new Blob([await book.xlsx.writeBuffer()],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),base(file.name)+'.xlsx','按文字坐标推断行列，合并单元格、复杂表格与扫描件需要人工校对。');}finally{await doc.loadingTask.destroy();}}
async function htmlToPdf(file,progress){await loadScript('dompurify.js');await loadScript('html2canvas.js');await loadScript('jspdf.js');const raw=await file.text();if(raw.length>3e6)throw new Error('HTML 内容超过 3 MB，请精简后重试');let clean=window.DOMPurify.sanitize(raw,{FORBID_TAGS:['script','iframe','object','embed','form','link','style','video','audio','svg'],FORBID_ATTR:['srcset','action','formaction']});const parsed=new DOMParser().parseFromString(clean,'text/html');for(const el of parsed.querySelectorAll('*')){if(el.tagName==='IMG'&&!el.getAttribute('src')?.startsWith('data:image/'))el.removeAttribute('src');if(el.hasAttribute('style')){const style=el.getAttribute('style');if(/url\s*\(|@import|expression\s*\(/i.test(style))el.removeAttribute('style');}el.removeAttribute('href');}clean=parsed.body.innerHTML;const frame=document.createElement('iframe');frame.sandbox='allow-same-origin';frame.style.cssText='position:fixed;left:-10000px;top:0;width:794px;height:1123px;border:0';frame.srcdoc=`<!doctype html><meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src data:; style-src 'unsafe-inline'"><style>body{margin:42px;font:16px/1.7 sans-serif;color:#263327;overflow-wrap:anywhere}img{max-width:100%}table{border-collapse:collapse}td,th{padding:8px;border:1px solid #ddd}</style>${clean}`;document.body.append(frame);try{await new Promise((r,j)=>{frame.onload=r;setTimeout(()=>j(new Error('HTML 排版超时')),15000);});const body=frame.contentDocument.body;if(body.scrollHeight>22000)throw new Error('HTML 页面过长，请拆分后转换');const canvas=await window.html2canvas(body,{backgroundColor:'#ffffff',scale:1.4,useCORS:false,allowTaint:false});return canvasAsPDF(canvas,base(file.name)+'.pdf',progress);}finally{frame.remove();}}
