async function excelToPdf(file,progress){await loadScript('exceljs.js');await loadScript('jspdf.js');await document.fonts.ready;const book=new window.ExcelJS.Workbook();await book.xlsx.load(await file.arrayBuffer());const pdf=new window.jspdf.jsPDF({unit:'mm',format:'a4',orientation:'landscape'});let pageIndex=0;for(const sheet of book.worksheets){if(sheet.rowCount>2000||sheet.columnCount>40)throw new Error('单个工作表最多支持 2000 行、40 列，请精简后转换');const cols=Math.max(sheet.columnCount,1),rows=sheet.rowCount,columnsPerPage=8;for(let startCol=1;startCol<=cols;startCol+=columnsPerPage){const visible=Math.min(columnsPerPage,cols-startCol+1),colW=1450/visible;for(let startRow=1;startRow<=Math.max(rows,1);startRow+=22){const canvas=document.createElement('canvas');canvas.width=1600;canvas.height=1132;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,1600,1132);ctx.fillStyle='#204b35';ctx.font='28px "Noto Sans SC","Microsoft YaHei",sans-serif';ctx.fillText(sheet.name,70,65);for(let row=0;row<Math.min(22,rows-startRow+1);row++){for(let col=0;col<visible;col++){const x=70+col*colW,y=100+row*42;ctx.strokeStyle='#dbe2d5';ctx.strokeRect(x,y,colW,42);ctx.save();ctx.beginPath();ctx.rect(x+6,y+3,colW-12,36);ctx.clip();ctx.fillStyle='#26362a';ctx.font='18px "Noto Sans SC","Microsoft YaHei",sans-serif';ctx.fillText(sheet.getRow(startRow+row).getCell(startCol+col).text,x+8,y+27);ctx.restore();}}if(pageIndex++)pdf.addPage();pdf.addImage(canvas.toDataURL('image/jpeg',.92),'JPEG',0,0,297,210);if(pageIndex>100)throw new Error('输出超过 100 页，请缩小表格');}}progress((sheet.id||1)/book.worksheets.length,'正在转换工作表…');}return result(pdf.output('blob'),base(file.name)+'.pdf','基础表格排版；公式使用文件中的缓存值，图表、图片、合并单元格和复杂格式不还原。');}
